"""Build the authorized Canva continuation, pages 9–36. First eight live pages stay untouched."""
from pathlib import Path
from html import escape as e
import json

OUT=Path(__file__).parents[3]/'outputs/m08-canva-revision'
OUT.mkdir(parents=True,exist_ok=True)
pages=[]
def table(headers,rows):
    return '<table><thead><tr>'+''.join('<th>'+e(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
def equation(formula,meaning):return f'<div class="equation"><b>{e(formula)}</b><p>{e(meaning)}</p></div>'
def timeline(a,b,direction='→',label='One year · 6% simple interest'):
    return f'<div class="timeline"><div><small>Today</small><strong>{e(a)}</strong></div><div class="direction"><span>{direction}</span>{e(label)}</div><div><small>Later</small><strong>{e(b)}</strong></div></div>'
def add(title,lead,body,prompt,location='',kind='concept'):
    n=len(pages)+9
    pages.append(dict(number=n,title=title,lead=lead,body=body,prompt=prompt,location=location,kind=kind))
def money(x):return f'${x:,.2f}'

add('Growing money moves it forward in time','Keep Meridian’s $1,000, 6%, one-year example.',timeline('$1,000','$1,060')+equation('=1000*(1+6%*1)','Simple future value = principal × (1 + annual rate × years)'),'The $1,060 includes the original $1,000 and $60 interest.')
add('Which starting amount earned $60?','Now the interest is known. The starting principal is missing.','<div class="big-equation"><strong>?</strong> × 6% × 1 year = $60</div>'+equation('=60/(6%*1)','Principal = interest ÷ (annual rate × years) = $1,000'),'We divided the interest earned, not the total ending balance.','Simple interest · C22')
add('Discounting brings the total back to today','Now the known amount is the $1,060 future receipt.',timeline('$1,000','$1,060','←')+equation('=1060/(1+6%*1)','Simple present value = future value ÷ (1 + annual rate × years)'),'Recovering principal from interest and discounting a total are different questions.','Simple interest · C23')
add('Build the interest and ending balance','Open Simple interest. Inputs: C17 = $1,000; C18 = 6%; C19 = 1 year.',table(['Cell','Your calculation'],[['C20','Calculate simple interest from the three inputs.'],['C21','Combine original principal and earned interest.']]),'Build with cell references. What is included in the ending balance?','Simple interest · C20:C21','build')
add('Check the forward calculation','Compare your formulas before changing anything.',table(['Cell','Formula','Result'],[['C20','=C17*C18*C19','$60.00'],['C21','=C17+C20','$1,060.00']])+timeline('$1,000','$1,060'),'Interest is only the addition. Future value is the whole balance.','Simple interest · C20:C21','reveal')
add('Bring the same money back to its start','Use the same inputs and your completed C20:C21.',table(['Cell','What is known?','What must you find?'],[['C22','Interest earned, annual rate, years','Original principal'],['C23','Total future value, annual rate, years','Value today']]),'Build both formulas. Predict whether the two answers should agree.','Simple interest · C22:C23','build')
add('Two routes recover the same $1,000','Each formula reverses a different relationship.',table(['Cell','Formula','Result'],[['C22','=C20/(C18*C19)','$1,000.00'],['C23','=C21/(1+C18*C19)','$1,000.00']]),'Both return C17 because they use the same simple-interest model, rate, and time.','Simple interest · C22:C23','reveal')
add('Checkpoint B: what must Meridian repay?','Meridian borrows $18,500 for 8 months at 6.2% annual simple interest.',table(['Cell','Build in this order'],[['G12','Convert D12 months using E12 months per year.'],['G13','Find interest using principal, rate, and linked years.'],['G14','Find the total repayment.']]),'Predict: will repayment exceed $18,500? Explain your result in B31:G33.','Live You Try It · G12:G14','build')
add('Debrief B: separate interest from principal','Eight months is 8/12 of a year.',table(['Cell','Formula','Result'],[['G12','=D12/E12','0.666667 years'],['G13','=D13*E13*F13','$764.67'],['G14','=D14+E14','$19,264.67']]),'The repayment returns $18,500 principal and adds $764.67 interest.','Live You Try It · G12:G14','reveal')
add('A day-based note uses the same logic','Meridian’s note: $32,000 principal, 4.5% annual rate, 80 exact-interest days.',table(['Row','A · Input / result','B · Value'],[[2,'Principal','$32,000'],[3,'Annual rate','4.5%'],[4,'Exact days','80'],[5,'Days per year','365'],[6,'Simple interest','Build here']])+equation('=B2*B3*(B4/B5)','80 ÷ 365 ≈ 0.219178 years → $315.62 interest'),'Build B6 on Note example. Then transfer the method to checkpoint A.','Note example · B6')
add('Checkpoint A: which year basis costs more?','Same $42,000 principal, 4.8% annual rate, and 75 actual days.',table(['Cells','Build'],[['G6 → G7','Exact time in years → exact interest'],['G8 → G9','Ordinary time in years → ordinary interest'],['G10','Ordinary interest minus exact interest']]),'Only the year basis changes. Predict first; explain the difference in B26:G28.','Live You Try It · G6:G10','build')
add('Debrief A: the smaller denominator matters','The prefilled F7 and F9 links carry each year fraction into its interest calculation.',table(['Cell','Formula','Result'],[['G6','=D6/E6','0.205479 years'],['G7','=D7*E7*F7','$414.25'],['G8','=D8/E8','0.208333 years'],['G9','=D9*E9*F9','$420.00'],['G10','=E10-D10','$5.75']]),'75/360 is larger than 75/365. Use the basis stated in the agreement.','Live You Try It · G6:G10','reveal')
add('What earns interest in the second year?','So far, only the original principal earns interest. What if earned interest stays invested?',table(['Model','After year 1','After year 2'],[['Simple interest','$1,000 + $60 = $1,060','$1,060 + $60 = $1,120'],['Annual compounding','$1,000 + $60 = $1,060','$1,060 + $63.60 = $1,123.60']])+equation('=C7*(1+C8)^C9','Present value tab: C10 uses simple growth; C11 uses compound growth.'),'Predict year 2 interest first. The prior $60 earns another $3.60 under compounding.','Present value · C10:C11','comparison')
add('Choose the model before discounting','Meridian will receive $1,120 after two years. Required annual return: 6%.',table(['Model','Formula','Value today'],[['Simple interest','=C12/(1+C8*C9)','$1,000.00'],['Annual compound','=C12/(1+C8)^C9','$996.80']]),'Both are valid under their stated assumptions. Our payment-stream challenge uses annual compounding.','Present value · C13:C14','comparison')
add('Excel’s negative PV is a cash-flow direction','Investor viewpoint: pay today; receive $1,120 at the end of year 2.',timeline('−$996.80','+$1,120','→','Two years · 6% annual compounding')+equation('=PV(C8,C9,0,C12)','C15: rate, years, no recurring payments, future receipt → −$996.80'),'Use =-PV(C8,C9,0,C12) in C14 to show the positive magnitude for comparison.','Present value · C14:C15')
add('Check by growing the payment forward','Use the signed PV already calculated in C15.',equation('=FV(C8,C9,0,C15)','C16 returns +$1,120: the negative outflow grows into a positive receipt.')+timeline('−$996.80','+$1,120','→','Same rate · same two years'),'A verification must use the same rate, time, and growth model.','Present value · C16')
add('Checkpoint C: what is the receipt worth today?','Meridian expects $30,000 in 2 years. Use 6.5% annual compound discounting.',table(['Cell','Your task'],[['G16','Calculate the signed present outflow.'],['G17','Display its positive magnitude.'],['G18','Verify the future receipt using the signed PV.']]),'Explain the sign and the verification in B36:G38. Use the inputs in rows 16–18.','Live You Try It · G16:G18','build')
cpv=30000/1.065**2
add('Debrief C: interpret both directions','A payment today and a receipt later have opposite signs.',table(['Cell','Formula','Result'],[['G16','=PV(E16,F16,0,D16)',money(-cpv)],['G17','=-D17',money(cpv)],['G18','=FV(E18,F18,0,D18)','$30,000.00']]),'The negative PV is an outflow, not a negative investment value. The FV check recovers the receipt.','Live You Try It · G16:G18','reveal')
add('Extension: express a wait in annual periods','Meridian expects $18,000 in 15 months at a 6% annual compound rate.','<div class="months"><div><strong>12 months</strong><span>1 annual period</span></div><div><strong>3 months</strong><span>0.25 annual period</span></div></div>'+equation('C23 = C21/C22     C24 = -PV(C20,C23,0,C19)','15/12 = 1.25 annual periods → $16,735.56 today'),'This example assumes fractional-period annual compound discounting. It is not simple interest.','Present value · C23:C24')
def bars(items,label):
    return '<div class="bars">'+''.join(f'<div class="barrow"><span>{e(k)}</span><div style="width:{v*7}px">{money(v)}</div></div>' for k,v in items)+f'<small>{e(label)}</small></div>'
add('Waiting longer lowers the value today','Keep the future receipt at $100 and the annual compound rate at 6%.',bars([(f'{t} year'+('s' if t!=1 else ''),100/1.06**t) for t in [1,3,5]],'Horizontal bar length = present value in dollars; common zero baseline.'),'Predict before comparing: why is the earliest receipt worth the most?','Present value · C31:E31','chart')
add('A higher required return lowers present value','Keep the future receipt at $100 and the wait at three years.',bars([(f'{r:.0%} annual rate',100/(1+r)**3) for r in [.04,.06,.08]],'Horizontal bar length = present value in dollars; common zero baseline.'),'Connect to the opening: what could make Meridian require a higher return?','Present value · D30:D32','chart')
add('Use both effects to predict the extremes','Before calculating, identify the highest and lowest PV in the worksheet grid.',table(['Annual rate / years','1','3','5'],[[f'{r:.0%}']+[money(100/(1+r)**t) for t in [1,3,5]] for r in [.04,.06,.08]])+equation('=-PV($B30,C$29,0,$C$27)','Build C30, copy across and down. $ locks the rate column, year row, and future receipt.'),'Highest: shortest wait + lowest rate. Lowest: longest wait + highest rate.','Present value · C30:E32','matrix')
add('Diagnose the model before the challenge','Same $18,000 receipt after two years; same 6% annual rate.',table(['Assumption','Formula','Value today'],[['Simple interest','=C36/(1+C37*C38)','$16,071.43'],['Annual compounding','=C36/(1+C37)^C38','$16,019.94']]),'The challenge states annual compounding. Explain which denominator fits before building.','Present value · C39:C40','comparison')
add('Bring one payment back before combining many','Worked example: a separate $10,000 receipt at the end of year 2; 6% annual compound rate.',timeline('$8,899.96','$10,000','←','Two years · annual compounding')+equation('=-PV(6%,2,0,10000)','Divide $10,000 by 1.06². This payment’s value today is $8,899.96.'),'For several payments: discount each to today, then add their present values.')
add('Challenge: which offer would you choose?','Meridian can receive $75,000 today or the future payment stream below. Use 6% annual compounding.',table(['Payment date','End year 1','End year 2','End year 3','End year 4','End year 5'],[['Receipt','$18,000','$22,000','$25,000','$20,000','$15,000']]),'Confirm E6. Build E12:E18; then recommend an offer in B19:E23 with one assumption that could change it.','Challenge · E12:E18 and B19:E23','build')
payments=[18000,22000,25000,20000,15000]
add('Every payment must end at the same date','Keep the annual discount rate fixed while each payment’s year changes.',table(['Cell','Year','Future receipt','Value today'],[[f'E{11+i}',i,money(v),money(v/1.06**i)] for i,v in enumerate(payments,1)])+equation('E12 = -PV($D$9,B12,0,C12)     E17 = SUM(E12:E16)','Copy E12 down to E16. Lock $D$9; let the year and receipt move with each row.'),'Sum unrounded values: $84,602.28. E18 compares that total with E6.','Challenge · E12:E18','reveal')
add('Recommend using value today and assumptions','Compare your evidence before revising your recommendation.','<div class="offers"><div><small>Cash today</small><strong>$75,000.00</strong></div><div><small>Future stream valued today</small><strong>$84,602.28</strong></div></div><div class="difference">Stream advantage today: <b>$9,602.28</b></div>','At the stated rate, Offer B has the higher PV. How could payment risk or a higher required return reverse that choice?','Challenge · B19:E23','decision')
add('Defend the model, then defend the decision','Return to our opening question: why can money today be worth more?','<div class="checks"><div><strong>Match the units</strong><p>Annual rate → years.<br>Months ÷ 12; days ÷ stated year basis.</p></div><div><strong>Match the model</strong><p>Simple or compound?<br>Use the same assumptions in every step.</p></div><div><strong>Match the date</strong><p>Bring all payments to today.<br>Then compare and explain.</p></div></div>','Opportunity cost, purchasing power, and payment risk inform the required return; do not add three percentages automatically.','', 'synthesis')
assert len(pages)==28
css='''*{box-sizing:border-box}body{margin:0;background:#ddd;font-family:"Georgia Pro",Georgia,serif;color:#0E1116}.page{width:1280px;height:720px;background:#FAF8F3;position:relative;padding:42px 54px 90px;border-top:12px solid #4A7C5E;overflow:hidden;margin:0 0 20px}.eyebrow{font-size:17px;color:#355773;letter-spacing:1px}h1{font-size:42px;line-height:1.13;margin:16px 0 14px;font-weight:bold}.lead{font-size:24px;line-height:1.35;margin:0 0 24px}.content{font-size:24px}.footer{position:absolute;bottom:26px;left:54px;right:54px;font-size:21px;line-height:1.3;border-top:2px solid #E5E1D6;padding-top:14px;display:flex;gap:20px;justify-content:space-between}.footer p{margin:0;max-width:1080px}.number{font-size:18px;color:#355773}.equation{background:#EAF3EC;border-left:5px solid #4A7C5E;padding:17px 23px;margin:20px 0;font-size:24px}.equation b{color:#355773;font-size:26px}.equation p{font-size:22px;line-height:1.3;margin:12px 0 0}.timeline{display:flex;align-items:center;justify-content:space-around;padding:25px 0;margin:22px 0}.timeline small,.offers small{display:block;font-size:23px;margin-bottom:14px}.timeline strong,.offers strong{font-size:48px;color:#355773}.direction{text-align:center;font-size:21px;max-width:440px}.direction span{display:block;font-size:60px;color:#4A7C5E}.big-equation{text-align:center;font-size:45px;padding:40px}.big-equation strong{font-size:80px;color:#4A7C5E}table{width:100%;border-collapse:collapse;font-size:23px;line-height:1.28}th{background:#355773;color:white;text-align:left;padding:14px}td{padding:14px;border-bottom:2px solid #E5E1D6}tr:nth-child(even) td{background:#F2EEE5}td:first-child{font-weight:bold;color:#355773}.build{border-top-color:#B8843D}.reveal .eyebrow{color:#4A7C5E}.months{display:flex;gap:25px;margin:35px 0}.months div:first-child{flex:4;background:#4A7C5E;color:white}.months div:last-child{flex:1;background:#EAF3EC}.months div{padding:25px}.months strong{display:block;font-size:35px}.months span{display:block;font-size:23px;margin-top:20px}.bars{padding:30px 0}.barrow{display:flex;align-items:center;margin-bottom:28px;gap:22px}.barrow>span{width:230px;font-size:26px}.barrow>div{background:#355773;color:white;padding:15px 20px;font-size:27px}.bars small{font-size:18px}.offers{display:flex;justify-content:space-around;margin:60px 0 40px}.difference{text-align:center;background:#EAF3EC;padding:25px;font-size:34px}.checks{display:flex;gap:32px;margin-top:65px}.checks>div{flex:1;border-top:5px solid #4A7C5E;padding-top:22px}.checks strong{font-size:30px}.checks p{font-size:25px;line-height:1.55}.matrix table{font-size:25px}.comparison table{font-size:24px}@media print{body{background:white}.page{margin:0;break-after:page}}'''
css+=' .compact table td,.compact table th{padding:8px 14px}.offers{margin:30px 0 25px}'
html='<!doctype html><html lang="en"><meta charset="utf-8"><title>BUS123 M08 — Revised continuation</title><style>'+css+'</style><body>'
for p in pages:
    eyebrow='BUS123 · MATH M08 · '+(p['location'] or 'Meridian Advisory Group')
    if p['kind']=='build':eyebrow+=' · Try first'
    if p['kind']=='reveal':eyebrow+=' · Debrief'
    html+=f'<section class="page {p["kind"]} {"compact" if p["number"] in [18,34] else ""}" data-document-role="page" data-label="{e(p["title"],quote=True)}"><div class="eyebrow">{e(eyebrow)}</div><h1>{e(p["title"])}</h1><p class="lead">{e(p["lead"])}</p><div class="content">{p["body"]}</div><footer class="footer"><p>{e(p["prompt"])}</p><span class="number">{p["number"]}</span></footer></section>'
html+='</body></html>'
(OUT/'bus123-math-m08-l01-canva-continuation.html').write_text(html)
(OUT/'sequence.json').write_text(json.dumps([{k:v for k,v in p.items() if k!='body'} for p in pages],indent=2))
print('Built 28 continuation pages: Canva pages 9–36.')
